import{_ as e,c as s,o as t,ag as i}from"./chunks/framework.CjE4jieZ.js";const n="/images/2026/lantransport-main.webp",o="/images/2026/lantransport-web.jpeg",k=JSON.parse('{"title":"LanTransport：把文件夹丢进局域网，对方打开浏览器就能拿","description":"","frontmatter":{"title":"LanTransport：把文件夹丢进局域网，对方打开浏览器就能拿","author":"welpher.yu","date":"2026-11-25T19:20:00.000Z","tags":["局域网","开源","Tauri"],"categories":["居家折腾"]},"headers":[],"relativePath":"posts/2026/lantransport.md","filePath":"posts/2026/lantransport.md"}'),r={name:"posts/2026/lantransport.md"};function p(l,a,d,h,c,g){return t(),s("div",null,[...a[0]||(a[0]=[i('<p>同一个 Wi-Fi 下传个文件，本来应该是最简单的事，实际却总要绕一大圈：微信先压一遍图，网盘要先传上去再下下来，U 盘拔来拔去。要是跨系统就更麻烦——Mac 上的资料给 Windows 同事、从 Linux 机器上拷点东西到笔记本、摄影现场把素材收到手机上，光是配 SMB、开共享、处理账号权限就够折腾一阵。</p><p>LanTransport 就是为了这一步做的：一个很小的桌面应用，选一个文件夹，点“开始共享”，同一个局域网里的任何设备——Mac、Windows、Linux、手机、平板——用浏览器打开链接，就能浏览和下载。发送端和接收端都不用配共享目录，也没有账号、云端和中继，文件不离开你的网络。</p><h2 id="它长什么样" tabindex="-1">它长什么样 <a class="header-anchor" href="#它长什么样" aria-label="Permalink to &quot;它长什么样&quot;">​</a></h2><p><img src="'+n+'" alt="LanTransport 主界面"></p><p>打开的界面就这么点东西：选文件夹、设端口、开始共享，然后拿到一个 <code>http://192.168.x.x:8000</code> 的地址和二维码。把地址发给对方，或者让对方扫一下，事情就结束了。</p><p>整个流程可以压缩成三步：</p><ol><li>选一个（或多个）要共享的文件夹</li><li>点 <strong>Start sharing</strong></li><li>把链接或二维码给对方</li></ol><p>默认是只读的。对方只能看和下载，不能改、不能删。</p><h2 id="接收方什么都不用装" tabindex="-1">接收方什么都不用装 <a class="header-anchor" href="#接收方什么都不用装" aria-label="Permalink to &quot;接收方什么都不用装&quot;">​</a></h2><p><img src="'+o+'" alt="接收端用浏览器打开共享页面"></p><p>这是它和“再做一个网盘”最大的区别：接收端零安装。手机、平板、另一台电脑，只要有浏览器就行。</p><p>截图是手机，但手机只是其中一种接收端。局域网里的另一台 Mac、Windows 笔记本、Linux 桌面，打开浏览器看到的是同一个页面。不用管对方是什么系统，也不用提前配 SMB、开共享文件夹或者处理账号权限——两台机器能互相访问到 IP 和端口就行。如果 Windows 第一次监听时弹出防火墙提示，放行即可。</p><p>发送端本身也是跨平台的：macOS（Intel 和 Apple Silicon）、Windows、Linux 用的是同一套代码。</p><p>页面里有目录列表、搜索、面包屑、文件大小和修改时间，图片和文本可以直接预览，其他文件点一下下载。下载走的是 HTTP Range，也就是支持断点续传，大文件传到一半断了可以接着来。</p><p>页面的语言会跟着访问者的浏览器走，目前有中文和英文，右上角也能手动切。</p><h2 id="几个顺手的设计" tabindex="-1">几个顺手的设计 <a class="header-anchor" href="#几个顺手的设计" aria-label="Permalink to &quot;几个顺手的设计&quot;">​</a></h2><p><strong>多个文件夹合并成一个列表。</strong> 不用把东西先归到一个目录里，添加几个文件夹，网页端看到的是合并后的内容；遇到同名文件会分行显示，并标出来自哪个文件夹。</p><p><strong>上传是可选的，而且要 key。</strong> 打开上传开关后会生成一个 10 位 key，存在链接里或者手动填。文件落在第一个共享文件夹的 <code>uploads/</code> 下，只增不改：不覆盖、不删除、不改名，重名自动加 <code> (1)</code>。key 可以随时轮换，适合“这次传完就作废”的场景。</p><p><strong>可以设置浏览密码。</strong> 走 HTTP Basic，用户名固定是 <code>share</code>。在咖啡馆、酒店、会场这类不完全可信的网络里，至少别让人随手点开就能看。</p><p><strong>关掉窗口不等于停止共享。</strong> 它是个托盘应用，关窗后还在后台跑，托盘里可以看状态、复制链接、开始或停止。</p><p><strong>只监听局域网。</strong> 没有“仅本机”和“暴露公网”的开关，因为它本来就不是内网穿透工具。这个限制是故意的。</p><h2 id="为什么安装包这么小" tabindex="-1">为什么安装包这么小 <a class="header-anchor" href="#为什么安装包这么小" aria-label="Permalink to &quot;为什么安装包这么小&quot;">​</a></h2><p>桌面端用的是 <strong>Tauri 2</strong>，界面交给系统自带的 WebView，而不是像 Electron 那样捆一个 Chromium。HTTP 服务是 Rust 里的精简实现，只覆盖用得到的部分：GET / HEAD / PUT、Range、超时和连接数上限，HTTP/1.1 也只实现需要的子集。整个应用没有 Node 或 Python 运行时，安装包只有几 MB。</p><p>线程模型很朴素：accept 循环加每连接一个线程，上限 64，局域网场景够用，也就没有引入异步运行时。</p><h2 id="安全边界得说清楚" tabindex="-1">安全边界得说清楚 <a class="header-anchor" href="#安全边界得说清楚" aria-label="Permalink to &quot;安全边界得说清楚&quot;">​</a></h2><p>这类工具最怕被当成“公网文件服务器”用，所以边界写在明面上：</p><ul><li><strong>没有 TLS。</strong> 浏览密码和上传 key 在局域网里是明文传输的，别在不可信网络里传敏感东西。</li><li><strong>默认没有认证。</strong> 不设密码时，能访问到这个端口的人都能看共享目录。</li><li><strong>只在可信局域网使用。</strong> 不要把端口映射到公网，它没有为此做任何防护。</li><li><strong>路径限制在共享根目录内。</strong> 每个请求都会 <code>canonicalize</code> 后检查是否越界，拒绝 <code>..</code>、隐藏文件和指向根目录外的符号链接。</li><li><strong>上传只写不覆盖。</strong> 先写隐藏临时文件再 rename，重名加后缀，不提供删除和重命名。</li></ul><p>浏览密码会以明文保存在本地配置文件里（Unix 下权限 <code>0600</code>），介意的话可以在输入框里点清除。更完整的威胁模型在仓库的 <code>SECURITY.md</code> 里。</p><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><p>macOS：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cask</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> welpher/tap/lantransport</span></span></code></pre></div><p>Windows：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">winget install welpher.LanTransport</span></span></code></pre></div><p>Arch Linux：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yay</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lantransport-bin</span></span></code></pre></div><p>其他平台可以直接去 <a href="https://github.com/welpher/lantransport/releases" target="_blank" rel="noreferrer">Releases</a> 下载 <code>.dmg</code>、<code>.exe</code> / <code>.msi</code>、<code>.AppImage</code> / <code>.deb</code> / <code>.rpm</code>。</p><p>需要说明的是，目前的构建<strong>还没有代码签名</strong>。macOS 第一次打开会被 Gatekeeper 拦，需要右键 → 打开；Windows 会弹 SmartScreen。这不是病毒，只是还没买证书。</p><h2 id="后面" tabindex="-1">后面 <a class="header-anchor" href="#后面" aria-label="Permalink to &quot;后面&quot;">​</a></h2><p>近期优先补的是代码签名和自动更新，然后是桌面端的上传进度和历史、按文件夹区分的上传链接，以及一个设备间传文本和图片的剪贴板通道。完整清单在仓库的 Roadmap 里。</p><p>项目是 MIT 协议，代码在 <a href="https://github.com/welpher/lantransport" target="_blank" rel="noreferrer">github.com/welpher/lantransport</a>。翻译、平台适配、issue 都欢迎。</p><p>如果经常需要在同一个 Wi-Fi 下互相传文件，可以装一个试试。它不解决所有问题，但“选个文件夹，对方打开浏览器就能拿”这件事，它做得足够直接。</p>',41)])])}const m=e(r,[["render",p]]);export{k as __pageData,m as default};
